class Solution:
    def addTwoNumbers(self, l1, l2, carry=0):
        if not l1 and not l2 and not carry:
            return None
        s = (l1.val if l1 else 0) + (l2.val if l2 else 0) + carry
        return ListNode(s % 10, self.addTwoNumbers(l1 and l1.next, l2 and l2.next, s // 10))

